var _markdown = "\n\n`sa` · 扩展 `default` · SCM 原生命令\n\n共 13 条。写法见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 创建 [#创建]\n\n<Opcode id=\"06B1\" name=\"CREATE_SEARCHLIGHT\" member=\"Searchlight.Create\">\n  创建探照灯（源点、指向点、两半径）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06B1 CREATE_SEARCHLIGHT\n      in: x, y, z, xPoint, yPoint, zPoint, radius, radiusPoint\n      out: handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local handle = createSearchlight(x, y, z, xPoint, yPoint, zPoint, radius, radiusPoint)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = Searchlight.create(x, y, z, xPoint, yPoint, zPoint, radius, radiusPoint)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 删除 [#删除]\n\n<Opcode id=\"06B2\" name=\"DELETE_SEARCHLIGHT\" member=\"Searchlight.Delete\">\n  删除探照灯。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06B2 DELETE_SEARCHLIGHT\n      in: self\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      deleteSearchlight(self)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Searchlight.delete(self)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 是否存在 [#是否存在]\n\n<Opcode id=\"06B3\" name=\"DOES_SEARCHLIGHT_EXIST\" member=\"Searchlight.DoesExist\">\n  handle 是否有效探照灯。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06B3 DOES_SEARCHLIGHT_EXIST\n      in: handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if doesSearchlightExist(handle) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (Searchlight.doesExist(handle)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 两点往返 [#两点往返]\n\n<Opcode id=\"06B4\" name=\"MOVE_SEARCHLIGHT_BETWEEN_COORDS\" member=\"Searchlight.MoveBetweenCoords\">\n  光束在两点间往返移动。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06B4 MOVE_SEARCHLIGHT_BETWEEN_COORDS\n      in: self, fromX, fromY, fromZ, toX, toY, toZ, speed\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      moveSearchlightBetweenCoords(self, fromX, fromY, fromZ, toX, toY, toZ, speed)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Searchlight.moveBetweenCoords(self, fromX, fromY, fromZ, toX, toY, toZ, speed)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 指向坐标 [#指向坐标]\n\n<Opcode id=\"06B5\" name=\"POINT_SEARCHLIGHT_AT_COORD\" member=\"Searchlight.PointAtCoord\">\n  光束移向坐标。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06B5 POINT_SEARCHLIGHT_AT_COORD\n      in: self, x, y, z, speed\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      pointSearchlightAtCoord(self, x, y, z, speed)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Searchlight.pointAtCoord(self, x, y, z, speed)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 指向角色 [#指向角色]\n\n<Opcode id=\"06B6\" name=\"POINT_SEARCHLIGHT_AT_CHAR\" member=\"Searchlight.PointAtChar\">\n  光束跟随角色。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06B6 POINT_SEARCHLIGHT_AT_CHAR\n      in: self, handle, speed\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      pointSearchlightAtChar(self, handle, speed)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Searchlight.pointAtChar(self, handle, speed)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 照到角色 [#照到角色]\n\n<Opcode id=\"06B7\" name=\"IS_CHAR_IN_SEARCHLIGHT\" member=\"Searchlight.IsCharIn\">\n  是否照到该角色。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06B7 IS_CHAR_IN_SEARCHLIGHT\n      in: self, handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if isCharInSearchlight(self, handle) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (Searchlight.isCharIn(self, handle)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 指向载具 [#指向载具]\n\n<Opcode id=\"06BF\" name=\"POINT_SEARCHLIGHT_AT_VEHICLE\" member=\"Searchlight.PointAtVehicle\">\n  光束跟随载具。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06BF POINT_SEARCHLIGHT_AT_VEHICLE\n      in: self, handle, speed\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      pointSearchlightAtVehicle(self, handle, speed)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Searchlight.pointAtVehicle(self, handle, speed)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 照到载具 [#照到载具]\n\n<Opcode id=\"06C0\" name=\"IS_VEHICLE_IN_SEARCHLIGHT\" member=\"Searchlight.IsVehicleIn\">\n  是否照到该载具。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06C0 IS_VEHICLE_IN_SEARCHLIGHT\n      in: self, handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if isVehicleInSearchlight(self, handle) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (Searchlight.isVehicleIn(self, handle)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 车上创建 [#车上创建]\n\n<Opcode id=\"06C1\" name=\"CREATE_SEARCHLIGHT_ON_VEHICLE\" member=\"Searchlight.CreateOnVehicle\">\n  在车上挂探照锥，指向某点。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06C1 CREATE_SEARCHLIGHT_ON_VEHICLE\n      in: vehicle, xOffset, yOffset, zOffset, xPoint, yPoint, zPoint, pointRadius, radius\n      out: handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local handle = createSearchlightOnVehicle(vehicle, xOffset, yOffset, zOffset, xPoint, yPoint, zPoint, pointRadius, radius)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = Searchlight.createOnVehicle(vehicle, xOffset, yOffset, zOffset, xPoint, yPoint, zPoint, pointRadius, radius)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 绑物体 [#绑物体]\n\n<Opcode id=\"06CA\" name=\"ATTACH_SEARCHLIGHT_TO_SEARCHLIGHT_OBJECT\" member=\"Searchlight.AttachToObject\">\n  绑到塔 / 罩 / 灯泡物体上。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      06CA ATTACH_SEARCHLIGHT_TO_SEARCHLIGHT_OBJECT\n      in: self, spotTower, spotHousing, spotBulb, xOffset, yOffset, zOffset\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      attachSearchlightToSearchlightObject(self, spotTower, spotHousing, spotBulb, xOffset, yOffset, zOffset)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Searchlight.attachToObject(self, spotTower, spotHousing, spotBulb, xOffset, yOffset, zOffset)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 碰撞裁剪 [#碰撞裁剪]\n\n<Opcode id=\"0941\" name=\"SET_SEARCHLIGHT_CLIP_IF_COLLIDING\" member=\"Searchlight.SetClipIfColliding\">\n  撞到物体是否裁剪光束。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0941 SET_SEARCHLIGHT_CLIP_IF_COLLIDING\n      in: self, state\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      setSearchlightClipIfColliding(self, state)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Searchlight.setClipIfColliding(self, state)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 地面阴影 [#地面阴影]\n\n<Opcode id=\"0A02\" name=\"SWITCH_ON_GROUND_SEARCHLIGHT\" member=\"Searchlight.SwitchOnGround\">\n  照射面是否显示地面阴影效果。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0A02 SWITCH_ON_GROUND_SEARCHLIGHT\n      in: self, state\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      switchOnGroundSearchlight(self, state)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Searchlight.switchOnGround(self, state)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
